function studyView(){const base=Object.fromEntries(Object.entries(session.study.config).filter(([k])=>!["selection","procurement"].includes(k))),v=draftValue("config",base);return"<h1>Procurement Savings Reconciliation Study Desk</h1><p>Follow an initiative from its approved baseline and commercial terms through actual purchases, explicit allocation, corrections and Finance decisions. Keep forecast, realized price difference, costs, avoidance and volume effects separate.</p>"+formOpen("config",base,"config")+"<div class='grid'>"+control("label","Study title",v.label)+control("data_class","Source class",v.data_class,{options:["operational","authored_course"]})+control("source_scope","Original source boundary",v.source_scope,{type:"textarea"})+control("returned_scope","Returned source boundary",v.returned_scope,{type:"textarea"})+control("authority_notes","Source rights and named reviewers",v.authority_notes,{type:"textarea"})+"</div><button type='submit'>Retain study scope</button></form><h2>Operator notes</h2><textarea id='study-notes' rows='5'>"+esc(draftValue("study-notes",{text:session.study.notes}).text)+"</textarea><button data-action='save-notes'>Retain notes</button><h2>Complete authored workflow</h2><p>The fictional worked course supplies original tracker and transaction files, supporting documents, baseline and mapping reviews, explicit shared purchase and cost allocations, signed adjustments, currency treatment, calculations and Finance history. The full initiative population and eight recurring work phases remain visible.</p><button data-action='course' data-course='complete'>Open complete authored workflow</button>";}

function intakeView(){const kind=(Core.KINDS.includes(session.selection.intakeKind)?session.selection.intakeKind:Core.KINDS[0]),side=(["source","returned"].includes(session.selection.intakeSide)?session.selection.intakeSide:"source"),key="intake:"+kind+":"+side,v=draftValue(key,null);let h="<h1>Original CSV and field mapping</h1><div class='actions'>"+Core.KINDS.map(k=>"<button data-action='intake-kind' data-kind='"+k+"'"+(k===kind?" aria-current='true'":"")+">"+esc(label(k))+"</button>").join("")+"</div><div class='actions'>"+["source","returned"].map(x=>"<button data-action='intake-side' data-side='"+x+"'"+(x===side?" aria-current='true'":"")+">"+(x==="source"?"Original source":"Returned trial")+"</button>").join("")+"</div><p>Retain the approved CSV extraction exactly. A blank mapping means the field was not observed; an empty cell in a mapped column is an observed blank. IDs are text, preserving leading zeros and punctuation. The current study retains every previously imported edition.</p><div class='actions'><label class='file-label'>Choose "+esc(kind)+" CSV<input type='file' data-file='csv:"+kind+":"+side+"' accept='.csv,text/csv'></label><button data-action='csv-template' data-kind='"+kind+"'>Download canonical header template</button></div>";
if(!v)return h+"<p>No pending file for this table and side. You can switch sections without losing another table's pending file or mapping.</p>";let t;try{t=Core.inspectCSV(v.content);}catch(e){return h+"<p class='notice'>"+esc(e.message)+"</p>";}h+="<h2>"+esc(v.name)+"</h2><p>"+t.rows.length+" parsed rows; exact original remains retained with this pending mapping.</p>"+formOpen(key,{},"intake")+"<div class='grid'>"+control("label","Extract edition label",v.label)+control("available_at","This complete edition was available at (UTC)",v.available_at??v.at,{help:"Enter when this complete CSV edition became available. Historical decisions also require each referenced original row, version and document to have been available at that decision time; a later retrospective extraction may retain those earlier originals."});
for(const field of Core.FIELDS[kind])h+=control("mapping."+field,label(field)+" ← original column",v.mapping[field],{options:["",...t.header],help:field===Core.ID_FIELDS[kind]?"Required stable source ID. Preserve exact original identifiers.":"Blank means unobserved; comparison will show it explicitly."});
h+="</div><button type='submit'>Retain original and select this extract</button> <button type='button' data-action='download-intake' data-key='"+esc(key)+"'>Download exact pending CSV</button></form><h2>Original row preview</h2><p>First 20 rows are shown; every parsed row is retained and compared.</p>"+table(["Original lines",...t.header],t.rows.slice(0,20).map(r=>[r.line_start+"–"+r.line_end,...r.values]));return h;}
function selectionView(){let h="<h1>Selected source and returned editions</h1><p>Each choice selects an exact original and mapping. Earlier extracts, mappings and comparisons remain in complete history. Choose a corrected returned export without replacing its first version.</p>";
for(const side of ["source","returned"]){h+="<h2>"+(side==="source"?"Original source":"Returned trial")+"</h2><div class='grid'>";for(const kind of Core.KINDS){const selected=session.study.config.selection[side][kind],es=session.study.extracts.filter(e=>e.kind===kind&&e.side===side);h+="<label>"+esc(label(kind))+"<select data-selection-kind='"+kind+"' data-selection-side='"+side+"'>"+optionsHtml(["",...es.map(e=>e.id)],selected,Object.fromEntries([["","No selected extract"],...es.map(e=>[e.id,e.label+" · "+session.study.originals.find(o=>o.id===e.original_id)?.name])]))+"</select></label>";}h+="</div>";}
h+="<h2>All retained extracts</h2>"+session.study.extracts.map(e=>"<div class='record'><strong>"+esc(e.label)+"</strong><small>"+esc(e.side+" · "+e.kind+" · available "+e.available_at+" · "+e.id)+"</small><button data-action='edit-extract' data-id='"+e.id+"'>Prepare mapping revision</button> <button data-action='download-original' data-id='"+e.original_id+"'>Download exact original</button></div>").join("");return h;}
function crosswalkView(){const kind=(Core.KINDS.includes(session.selection.mapKind)?session.selection.mapKind:Core.KINDS[0]),key="crosswalk:"+kind,base={kind,pairs:session.study.crosswalks.filter(x=>x.kind===kind).map(x=>({source_id:x.source_id,target_id:x.target_id}))},v=draftValue(key,base),src=Core.rows(session.study,kind,"source"),dst=Core.rows(session.study,kind,"returned");let h="<h1>Explicit identity maps</h1><div class='actions'>"+Core.KINDS.map(k=>"<button data-action='map-kind' data-kind='"+k+"'"+(k===kind?" aria-current='true'":"")+">"+esc(label(k))+"</button>").join("")+"</div><p>Pair original IDs to returned IDs explicitly. Names and external-system references are separate evidence, not automatic identity matches. Suppliers, items, initiatives, original purchases, allocation identities and frozen calculation inputs retain distinct explicit identities.</p><button data-action='match-ids' data-kind='"+kind+"'>Add unique exact-ID pairs; keep existing choices</button>"+formOpen(key,base,"crosswalk")+"<div class='table-wrap'><table><thead><tr><th>Original ID</th><th>Returned ID</th><th>Draft action</th></tr></thead><tbody>";
v.pairs.forEach((p,i)=>{h+="<tr><td>"+control("pairs."+i+".source_id","Original identity",p.source_id,{options:["",...src.map(r=>r.values.id).filter(Boolean)]})+"</td><td>"+control("pairs."+i+".target_id","Returned identity",p.target_id,{options:["",...dst.map(r=>r.values.id).filter(Boolean)]})+"</td><td><button type='button' data-action='remove-pair' data-index='"+i+"'>Remove draft pair</button></td></tr>";});h+="</tbody></table></div><button type='button' data-action='add-pair'>Add pair</button> <button type='submit'>Apply complete "+esc(kind)+" map</button></form><h2>Original identity context</h2>"+table(["ID","Original fields","Original row"],src.map(r=>[r.values.id,Object.entries(r.values).filter(([k])=>k!=="id").map(([k,v])=>k+": "+fmt(v)).join(" · "),r.source.name+":"+r.source.line_start+"–"+r.source.line_end]));return h;}
function documentsView(){const base={side:"source",kind:"spend_lines",record_id:"",document_id:"",notes:"",available_at:now()},v=draftValue("document-link",base),kind=Core.KINDS.includes(v.kind)?v.kind:null,side=v.side==="returned"?"returned":"source";let h="<h1>Exact supporting originals</h1><p>Retain actual supplier quotations, contracts, baseline evidence, purchase and AP extracts, allocation decisions, credit notes, policy documents and Finance decisions as exact bytes. Same filenames with different bytes remain distinct. Link to the exact typed source or returned record; names and captions do not establish identity. Links here annotate the selected supplied export, while source capture and availability dates remain in their exact retained editions.</p><label class='file-label'>Retain exact file<input type='file' data-file='document'></label>"+session.study.documents.map(d=>"<div class='record'><strong>"+esc(d.name)+"</strong><small>"+esc(d.media_type)+" · available "+esc(d.available_at)+" · "+d.bytes+" bytes · "+esc(d.id)+"</small><div class='mono'>"+esc(d.sha256)+"</div><p>"+esc(d.notes)+"</p><button data-action='download-document' data-id='"+d.id+"'>Download exact original</button> <button data-action='edit-document-availability' data-id='"+d.id+"'>Record source availability</button>"+(["image/png","image/jpeg","image/webp","image/gif","audio/mpeg","audio/wav","audio/ogg","audio/mp4","video/mp4","video/webm"].includes(d.media_type)?" <button data-action='preview-document' data-id='"+d.id+"'>Preview retained original</button>":"")+"</div>").join("");
const preview=session.study.documents.find(d=>d.id===session.selection.previewDocument);if(preview&&["image/png","image/jpeg","image/webp","image/gif"].includes(preview.media_type))h+="<figure><img style='max-width:100%;max-height:480px;object-fit:contain' src='data:"+esc(preview.media_type)+";base64,"+preview.base64+"' alt='"+esc(preview.name)+"'><figcaption>"+esc(preview.name+" · "+preview.sha256)+"</figcaption></figure>";
if(preview&&["audio/mpeg","audio/wav","audio/ogg","audio/mp4","video/mp4","video/webm"].includes(preview.media_type)){const tag=preview.media_type.startsWith("audio/")?"audio":"video";h+="<figure><"+tag+" controls preload='metadata' style='max-width:100%' src='data:"+esc(preview.media_type)+";base64,"+preview.base64+"'></"+tag+"><figcaption>"+esc(preview.name+" · "+preview.sha256)+"</figcaption></figure>";}
const dv=draftValue("document-availability",null);if(dv)h+="<h2>Source-backed document availability</h2>"+formOpen("document-availability",dv,"document-availability")+"<p class='mono'>"+esc(dv.document_id)+"</p><div class='grid'>"+control("available_at","Available in source (UTC)",dv.available_at)+control("reason","Original source or evidence supporting this availability",dv.reason,{type:"textarea"})+control("at","Recorded into this study (UTC)",dv.at)+"</div><button type='submit'>Retain availability correction</button></form>";
return h+"<h2>Link original to an exact record</h2>"+(!kind?"<p role='alert'>The retained draft names an unavailable record family: "+esc(v.kind)+". Choose an actual family before linking this original; the recovered value remains in this draft.</p>":"")+formOpen("document-link",base,"document-link")+"<div class='grid'>"+control("side","Evidence side",v.side,{options:["source","returned"]})+control("kind","Record kind",v.kind,{options:Core.KINDS})+control("record_id","Exact record ID",v.record_id,{options:["",...(kind?Core.rows(session.study,kind,side):[]).map(x=>x.values.id).filter(Boolean)]})+control("document_id","Original document",v.document_id,{options:["",...session.study.documents.map(d=>d.id)]})+control("available_at","This exact record/document link was available at (UTC)",v.available_at,{help:"Source-backed link availability, separate from this file’s capture time."})+control("notes","Source link and extraction notes",v.notes,{type:"textarea"})+"</div><button type='submit'"+(!kind?" disabled":"")+">Retain explicit document link</button></form>"+table(["Side","Kind","Record ID","Document ID","Notes"],session.study.document_links.map(x=>[x.side,x.kind,x.record_id,x.document_id,x.notes]))+session.study.document_links.map((x,i)=>"<p>"+esc(x.side+" / "+x.kind+" / "+x.record_id+" / "+x.document_id)+" <button data-action='unlink-document' data-index='"+i+"'>Remove this link; retain earlier edition</button></p>").join("");}
function compareView(){const a=M.assess(session);if(!a.ok)return"<h1>Comparison</h1><p class='notice'>"+esc(a.error)+"</p>";const r=a.result;let h="<h1>Supplied-return record comparison</h1><p class='notice'>"+esc(r.data_class)+" · "+esc(r.comparison_state)+" · "+esc(r.decision)+"</p><p>Original: "+esc(r.scope.source)+"</p><p>Returned: "+esc(r.scope.returned)+"</p>"+table(["Record kind","Original rows","Returned rows"],Core.KINDS.map(k=>[label(k),r.counts[k].source,r.counts[k].returned]))+"<h2>Exact differences and unresolved evidence</h2>"+table(["Finding","Kind / side","ID / field","Expected","Returned","Original row","Detail"],r.findings.map(x=>[x.code,x.kind+" / "+x.side,x.record_id+" / "+x.field,fmt(x.expected),fmt(x.actual),x.source?x.source.name+":"+x.source.line_start+"–"+x.source.line_end:"",x.detail]))+"<h2>Retained photo and document bytes</h2>"+table(["Kind","Original record","Returned record","Byte comparison","Original hashes","Returned hashes"],r.document_comparisons.map(d=>[d.kind,d.source_id,d.returned_id,d.state,d.source_sha256.join(", "),d.returned_sha256.join(", ")]))+"<p>Unobserved means neither side supplied linked document bytes. A matching reference alone does not establish matching attachment contents.</p><h2>Column availability</h2><p>Unobserved fields are distinct from source-observed blank cells. The export includes an explicit availability manifest.</p>"+table(["Kind / side","Extract","Unobserved columns"],Core.availability(session.study).tables.map(t=>[t.kind+" / "+t.side,t.extract_id||"None",Object.entries(t.fields).filter(([k,v])=>!v.observed).map(([k])=>k).join(", ")]))+"<h2>Interpretation</h2><p>"+esc(r.limits)+"</p><p>Equal counts alone do not establish transfer fidelity. A recorded acceptance leaves every difference visible. Review the exact selected record boundary and every unresolved identity before preparing the next trial.</p><p class='mono'>"+esc(r.study_sha256)+"</p><div class='actions'><button data-action='report'>Download comparison report</button><button data-action='export-zip'>Download complete working export</button></div>";return h;}
function reviewsView(){const base=M.reviewDraft(session),v=draftValue("review",base),stale=v.study_sha256!==Core.digest(session.study),r=Core.analyze(session.study);return"<h1>Named procurement and Finance review</h1><p>Review applies to the complete current source, selected extracts, maps and document links. Earlier decisions remain historical after a change. Each configured role must accept this exact edition. A later decision supersedes that role's earlier decision for the same digest.</p>"+(stale?"<p class='notice'>This pending review belongs to an earlier edition. Its notes remain retained.</p><button data-action='new-review'>Start current review; retain earlier draft</button>":"")+formOpen("review",base,"review")+"<div class='grid'>"+control("role","Review role",v.role,{options:session.study.config.procurement.required_review_roles})+control("reviewer","Reviewer",v.reviewer)+control("at","Reviewed at (UTC)",v.at)+control("decision","Decision",v.decision,{options:["accepted","revise"]})+control("notes","Review findings and next source correction",v.notes,{type:"textarea"})+"</div><button type='submit'>Record review</button></form>"+table(["Role / reviewer","Time","Decision","Edition","Notes"],session.study.reviews.map(x=>[x.role+" / "+x.reviewer,x.at,x.decision,x.study_sha256===r.study_sha256?"Current":"Earlier",x.notes]));}


function recordBase(kind,side){const selected=Core.selected(session.study,kind,side);return{kind,side,row_index:null,expected_extract_id:selected?.id||null,study_id:session.study.id,reason:"",at:now(),value:Object.fromEntries(Core.FIELDS[kind].map(k=>[k,!selected||selected.mapping[k]?"":null]))};}
function recordsView(){const kind=Core.KINDS.includes(session.selection.recordKind)?session.selection.recordKind:Core.KINDS[0],side=["source","returned"].includes(session.selection.recordSide)?session.selection.recordSide:"returned",key="record:"+kind+":"+side,base=recordBase(kind,side),v=draftValue(key,base),rs=Core.rows(session.study,kind,side);let h="<h1>Record an observation or correction</h1><p>Keep actual source identities and times. Operator and site context, initiatives, baseline evidence, original transactions, allocations, calculations, Finance decisions and recurring work each retain their source records. Each correction retains the original extract and the entire preceding study.</p><div class='actions'>"+Core.KINDS.map(k=>"<button data-action='record-kind' data-kind='"+k+"'>"+esc(label(k))+"</button>").join("")+"</div><div class='actions'>"+["source","returned"].map(x=>"<button data-action='record-side' data-side='"+x+"'>"+esc(label(x))+"</button>").join("")+"</div><button data-action='new-record'>Start new record; retain draft</button>";
h+="<div class='table-wrap'><table><thead><tr><th>ID</th><th>Selected values</th><th>Action</th></tr></thead><tbody>"+rs.map((r,i)=>"<tr><td>"+esc(r.values.id)+"</td><td>"+esc(Object.entries(r.values).filter(([k])=>k!=="id").map(([k,v])=>k+": "+fmt(v)).join(" · "))+"</td><td><button data-action='edit-record' data-index='"+i+"'>Prepare correction</button></td></tr>").join("")+"</tbody></table></div>";
h+=formOpen(key,base,"record")+"<h2>"+(v.row_index===null?"New observed record":"Correction to retained row")+"</h2><div class='grid'>";for(const k of Core.FIELDS[kind])h+=v.value[k]===null?"<p>"+esc(label(k))+": unobserved column. Prepare an explicit source mapping to add this field.</p>":control("value."+k,label(k),v.value[k],{type:(["notes","description","source_ref","meaning","exclusion_reason","package_description"].includes(k)||k.endsWith("_json"))?"textarea":"text",help:fieldHelp(kind,k),options:recordOptions(kind,k)});
if(["baseline_inputs","mapping_inputs","calculation_inputs","baseline_reviews","mapping_reviews","submissions","finance_reviews"].includes(kind))h+="<fieldset><legend>Bind exact supplied source</legend><button type='button' data-action='record-procurement-bindings'>Copy exact source or decision binding</button><p>Enter the original row identities above. This copies the current selected source hashes into the pending record. Actual baseline, procurement and Finance decision times remain supplied observations.</p></fieldset>";
return h+control("reason","Source-backed reason for this record or correction",v.reason,{type:"textarea"})+control("at","Recorded into this study (UTC)",v.at)+"</div><button type='submit'>Retain complete record revision</button></form>";}
function reportInputControls(){return "";}
function recordOptions(kind,k){
 if(k==="record_status")return["active","void"];
 if(["included","population_complete","phase_complete","inputs_complete"].includes(k))return["","true","false"];
 if(k==="decision")return kind==="finance_reviews"?["accepted","adjusted","rejected","revise"]:["accepted","rejected"];
 if(k==="family")return kind==="population_members"?["initiatives"]:Core.KINDS;
 if(k==="source_family")return Core.KINDS;
 if(k==="permission")return["procurement","finance","data","operations"];
 if(k==="baseline_kind")return["historical_paid","contract","budget","market","opening_quote"];
 if(k==="comparability")return["comparable","normalized","unresolved"];
 if(k==="effect_method")return["current_price_volume_with_interaction","baseline_price_volume"];
 if(["one_time_treatment","recurring_treatment"].includes(k))return["subtract","report_only"];
 if(kind==="costs"&&k==="kind")return["one_time","recurring"];
 if(kind==="spend_adjustments"&&k==="kind")return["credit","return","rebate","correction","reversal"];
 if(k==="state"&&kind==="initiative_events")return["planned","active","implemented","cancelled","completed","paused"];
 if(k==="phase")return Procurement.phases;
 if(k==="method")return[session.study.config.procurement.baseline_method,session.study.config.procurement.current_method];
 if(k.endsWith("_document_id"))return["",...session.study.documents.map(d=>d.id)];
 const side=["source","returned"].includes(session.selection.recordSide)?session.selection.recordSide:"returned";
 const exact={initiative_record_id:"initiatives",policy_record_id:"policies",baseline_record_id:"baselines",term_record_id:"commercial_terms",forecast_record_id:"forecasts",spend_record_id:"spend_lines",adjustment_record_id:"spend_adjustments",assignment_record_id:"assignments",mapping_case_record_id:"mapping_cases",mapping_review_record_id:"mapping_reviews",calculation_case_record_id:"calculation_cases",submission_record_id:"submissions",actual_rate_record_id:"fx_rates",constant_rate_record_id:"fx_rates"};
 if(exact[k])return["",...Core.rows(session.study,exact[k],side).map(r=>r.values.id).filter(Boolean)];
 const natural={operator_id:"operators",site_id:"sites",supplier_id:"suppliers",item_id:"items",person_id:"people",owner_id:"people",prepared_by:"people",reviewed_by:"people",approved_by:"people",agreed_by:"people",proposed_by:"people",assigned_by:"people",attributed_by:"people",posted_by:"people",generated_by:"people",submitted_by:"people",actor_id:"people",granted_by:"people"};
 if(natural[k]&&natural[k]!==kind)return["",...new Set(Core.rows(session.study,natural[k],side).map(r=>r.values[Procurement.IDS[natural[k]]]).filter(Boolean))];
 if(k==="record_id"||k==="source_record_id"){const v=draftValue("record:"+kind+":"+side,recordBase(kind,side)).value,f=k==="record_id"?v.family:v.source_family;if(Core.KINDS.includes(f))return["",...Core.rows(session.study,f,side).map(r=>r.values.id).filter(Boolean)];}
 return null;
}

function fieldHelp(kind,k){
 if(k==="id")return"Immutable identity of this exact original source version.";
 if(k==="record_key")return"Stable business identity across retained revisions.";
 if(k==="recorded_at")return"Actual recording time of this source version.";
 if(k==="available_at")return"First availability of this exact source version; retain separately from later CSV extraction.";
 if(["row_sha256","baseline_basis_sha256","mapping_basis_sha256","calculation_basis_sha256","submission_sha256"].includes(k))return"Use the exact supplied-source binding helper below after retaining the referenced originals.";
 if(k==="transaction_amount")return"Signed amount of the whole original cost transaction, before allocation across initiatives.";
 if(k==="allocation_key")return"Stable identity of this allocation within the original cost transaction. Repeated aliases must use the same key.";
 if(k==="amount"&&kind==="costs")return"Signed amount explicitly allocated to this initiative; retain the original transaction total separately.";
 if(k==="assigned_quantity")return"Explicit quantity allocated from this purchase. Total allocations may not exceed its actual quantity.";
 if(k==="allocation_basis_document_id")return"Original evidence supporting the actual cost split and attributable period.";
 if(k==="net_amount"&&kind==="spend_lines")return"Observed actual net item amount; preserve any difference from quantity × unit price.";
 if(k==="person_minutes")return"Observed active person-minutes; waiting and unmeasured setup remain separate.";
 if(k==="work_key")return"Stable actual work identity; copied rows cannot create extra work.";
 if(k==="factor_to_base")return"Documented conversion for this exact item and unit; no inferred pack size.";
 if(k==="rate_to_target")return"Original approved rate in target currency per one unit of source currency.";
 if(k==="expected_inputs")return"Count of the complete frozen original input set for this named decision.";
 if(k==="valid_to"||k==="ended_at")return"An observed blank means an open interval. An unmapped source field remains unknown.";
 return"";
}

function planView(){const base=session.study.config.procurement,v=draftValue("procurement-plan",base);let h="<h1>Complete initiative population and recurring work</h1><p>Include pending, cancelled, negative, rejected, partially realized and unresolved initiatives in the consecutive period. Source-family counts cover retained original versions. Complete population and supported amounts are assessed separately.</p>"+formOpen("procurement-plan",base,"procurement-plan")+"<div class='grid'>"+control("as_of","Study source cutoff",v.as_of)+control("population_start","Consecutive period start",v.population_start)+control("population_end","Consecutive period end",v.population_end)+control("operator_id","Measured operator ID",v.operator_id)+control("site_id","Site ID; blank for all operator sites",v.site_id)+control("population_key","Study population reference",v.population_key)+control("population_complete","Complete initiative inventory attested",v.population_complete,{type:"boolean"})+control("expected_members","Expected initiatives; blank unknown",v.expected_members,{type:"number",nullable:true})+control("side","Selected source side",v.side,{options:["source","returned"]})+control("baseline_method","Baseline work method",v.baseline_method)+control("current_method","Current work method",v.current_method)+control("notes","Population, policy, comparable work and exclusions",v.notes,{type:"textarea"})+"<label>Required phases, comma separated<input data-path='required_effort_phases' data-roles='1' value='"+esc(v.required_effort_phases.join(", "))+"'></label><label>Required study review roles, comma separated<input data-path='required_review_roles' data-roles='1' value='"+esc(v.required_review_roles.join(", "))+"'></label>"+control("source_population_complete","Complete source inventory attested",v.source_population_complete,{type:"boolean"});for(const k of Core.KINDS)h+=control("expected_counts."+k,label(k)+" expected source rows",v.expected_counts[k],{type:"number",nullable:true});return h+"</div><button type='submit'>Retain complete plan</button></form>";}

function timelineView(){
 const r=Core.analyze(session.study).procurement,p=r.population;let h="<h1>Initiatives and source reconciliation</h1>"+table(["Expected","Observed","Included","Excluded","Unresolved","Complete"],[[p.expected??"Unknown",p.observed,p.included,p.excluded,p.unresolved,p.complete]]);
 if(!r.operating)return h+"<p>Set the complete study period, named operator and source cutoff in Population & work plan.</p>";
 h+="<h2>Every observed initiative</h2>"+table(["Initiative","Name","State","Reporting currency","Complete"],(r.initiatives||[]).map(x=>[x.initiative_record_id,x.name,x.state,x.reporting_currency,x.complete]));
 h+="<h2>Actual purchase allocation</h2><p>One economic purchase is counted once across source aliases. Accepted mappings and explicit allocated quantities retain the unused remainder. Conflicting aliases, unmatched purchases and over-allocation remain visible.</p>"+detailRows(r.transactions,"Original transactions",["transaction_key","economic_key","spend_record_id","id"])+detailRows(r.mappings,"Mapping decisions",["mapping_case_record_id","id"])+detailRows(r.adjustments,"Signed credits, returns and corrections",["adjustment_record_id","id"]);
 const e=r.effort||{};h+="<h2>All recurring work phases</h2><p>Compare observed active person-minutes for the same full initiative population. Increased review and correction remain included. Unmeasured setup and unpaired observations are shown separately.</p>"+table(["Complete","Matched phase groups","Baseline minutes","Current minutes","Current minus baseline"],[[e.complete,e.matched_groups,displayValue(e.baseline_person_minutes),displayValue(e.current_person_minutes),displayValue(e.change_person_minutes)]])+detailRows(e.pairs||[],"Matched work groups",["member_id","matched_group_id"])+detailRows((e.records||[]).filter(x=>(e.unpaired_record_ids||[]).includes(x.record_id)),"Unpaired work",["id","member_id"]);
 h+="<h2>Additional observed work</h2>"+table(["Known matched baseline","Known matched current","All observed current minutes","Current inventory complete","Setup observed","Setup minutes"],[[displayValue(e.matched_known_baseline),displayValue(e.matched_known_current),displayValue(e.all_observed_current_person_minutes),e.all_current_complete,e.setup_observed,displayValue(e.setup_person_minutes)]]);
 return h+detailRows(p.members||[],"Complete population membership",["member_id","record_id"])+"<h2>Source issues</h2>"+table(["Code","Family","Record","Detail"],(r.issues||[]).map(x=>[x.code,x.family,x.id,x.detail]));
}
function displayValue(x){if(x===null||x===undefined)return"Unobserved";if(typeof x!=="object")return String(x);if(x.decimal!==undefined)return String(x.decimal);return JSON.stringify(x);}
function detailRows(xs,title,ids=[]){const values=Array.isArray(xs)?xs:Object.entries(xs||{}).map(([key,value])=>({key,value}));let h="<h2>"+esc(title)+"</h2>";if(!values.length)return h+"<p>No resolved observations in this source view.</p>";return h+values.map((x,i)=>"<details class='record'><summary>"+esc(ids.map(k=>x[k]).find(v=>v!==undefined&&v!==null)||x.key||"Record "+(i+1))+"</summary><pre class='mono'>"+esc(JSON.stringify(x,null,2))+"</pre></details>").join("");}


function emergencyView(){return !hasEmergency()?"":"<section class='notice'><h2>Pending input retained in memory</h2><p>"+esc(emergency.reason)+"</p><button data-action='download-session'>Download complete emergency recovery</button><button data-action='clear-emergency'>Download and clear pending input</button>"+Object.entries(emergency.drafts).map(([k])=>"<p>Pending form: "+esc(k)+"</p>").join("")+emergency.imports.map(p=>"<p>"+esc(p.name)+" <button data-action='download-emergency-import' data-key='"+esc(p.key)+"'>Download exact file</button></p>").join("")+"</section>";}

function recoveryView(){return emergencyView()+"<h1>Save & recover</h1><p>Download the complete session to move between browsers or keep an independent copy. It includes the study, all unfinished forms, review history, source originals and retained browser branches.</p><div class='actions'><button data-action='download-session'>Download complete session</button><button data-action='export-zip'>Download complete export ZIP</button><button data-action='export-source'>Download application source ZIP</button><label class='file-label'>Open session or study JSON<input type='file' data-file='session' accept='.json,application/json'></label></div>"+(conflict?"<div class='notice'><h2>Choose how to continue</h2><p>The saved copy changed in another tab. Both copies are retained. Selecting your browser branch acknowledges the current saved copy in one atomic transaction; it remains available below.</p><button data-action='adopt-local'>Keep this browser branch; retain saved copy</button><button data-action='open-saved'>Open saved copy; retain this branch</button></div>":"")+"<h2>Retained full branches</h2>"+(session.backups.length?session.backups.map(b=>"<div class='record'><strong>"+esc(b.reason)+"</strong><small>"+esc(b.at)+" · "+esc(M.branchInfo(session,b).title)+" · revision "+M.branchInfo(session,b).revision+"</small><div class='actions'><button data-action='download-branch' data-id='"+b.hash+"'>Download complete branch</button><button data-action='open-branch' data-id='"+b.hash+"'>Open branch (retain current)</button></div></div>").join(""):"<p>No prior branch has been replaced.</p>")+"<h2>Retained import candidates</h2>"+Object.entries(session.drafts).filter(([k])=>k.startsWith("pending-import:")).map(([k,p])=>"<div class='record'><strong>"+esc(p.name)+"</strong><p>"+esc(p.error)+"</p><button data-action='download-pending' data-key='"+esc(k)+"'>Download original candidate</button><button data-action='retry-pending' data-key='"+esc(k)+"'>Retry against current study</button></div>").join("")+"<h2>Study edition history</h2>"+session.history.map((h,i)=>"<div class='record'><span>"+esc(h.at+" — "+h.reason)+"</span><button data-action='restore-edition' data-index='"+i+"'>Restore study edition (retain current session)</button></div>").join("");}

function commerceView(){
 const r=Core.analyze(session.study).procurement;if(!r.operating)return"<h1>Savings reconciliation and Finance</h1><p>Set the study period, named operator and source cutoff.</p>";
 const totals=r.currency_totals||[],n=displayValue;let h="<h1>Savings reconciliation and Finance</h1><p>Forecast, calculated realized price difference, allocated costs, net result, documented avoidance and Finance-approved amounts retain their own meanings. Volume and interaction explain the spend bridge. Each reporting currency remains separate.</p>";
 h+="<h2>Complete totals by reporting currency</h2>"+table(["Currency","Initiatives","Forecast","Realized price difference","Net result","Avoidance","Submitted net","Approved net"],totals.map(x=>[x.currency,x.initiative_count,n(x.totals?.forecast),n(x.totals?.calculated_price),n(x.totals?.calculated_net),n(x.totals?.calculated_avoidance),n(x.totals?.submitted_net),n(x.totals?.approved_net)]));
 h+="<h2>Supported subtotals</h2><p>These are the supported portions of the population. An unresolved complete total remains unobserved above.</p>"+table(["Currency","Forecast subtotal","Price subtotal","Net subtotal","Avoidance subtotal","Submitted net subtotal","Approved net subtotal"],totals.map(x=>[x.currency,n(x.known_subtotals?.forecast),n(x.known_subtotals?.calculated_price),n(x.known_subtotals?.calculated_net),n(x.known_subtotals?.calculated_avoidance),n(x.known_subtotals?.submitted_net),n(x.known_subtotals?.approved_net)]));
 const metricNames={forecast:"Recomputed forecast",calculated_price:"Calculated realized price",calculated_net:"Calculated net",calculated_avoidance:"Calculated avoidance",submitted_price:"Submitted price",submitted_net:"Submitted net",submitted_avoidance:"Submitted avoidance",approved_price:"Finance-approved price",approved_net:"Finance-approved net",approved_avoidance:"Finance-approved avoidance"};
 h+="<details class='record'><summary>Metric completeness</summary><p>Complete means every included initiative has a supported result for that measure. A supported subtotal can remain available while the whole measure is unresolved.</p>"+table(["Currency","Measure","Whole population complete"],totals.flatMap(x=>Object.entries(metricNames).map(([key,label])=>[x.currency,label,x.completeness?.[key]===true?"Yes":"Unresolved"])))+"</details>";
 const cases=r.calculations||[];
 h+="<h2>Frozen calculation results</h2><p>Each row retains its exact original input basis. Values from a case marked For review remain calculation detail and do not become an accepted complete result.</p>"+table(["Case","Currency","State","Planned quantity","Actual quantity","Recomputed forecast","Realized price difference","Net","Avoidance"],cases.map(x=>[x.record_id,x.reporting_currency,x.complete?"Complete":"For review",n(x.computed?.planned_quantity),n(x.computed?.actual_quantity),n(x.computed?.recomputed_forecast),n(x.computed?.realized_price),n(x.computed?.net),n(x.computed?.avoidance)]));
 h+="<h2>Exact planned-to-actual spend bridge</h2>"+table(["Case","Currency","Planned baseline","Actual at constant FX","Actual at actual FX","FX difference","Price adherence","Volume","Interaction","Spend difference","Bridge equal"],cases.map(x=>[x.record_id,x.reporting_currency,n(x.computed?.planned_baseline_spend),n(x.computed?.actual_amount_constant_currency),n(x.computed?.actual_amount_at_actual_fx),n(x.computed?.fx_difference),n(x.computed?.price_adherence),n(x.computed?.volume),n(x.computed?.interaction),n(x.computed?.spend_difference),x.computed?.bridge_equal??"Unobserved"]));
 h+=detailRows(cases,"Complete calculation sources and decisions",["record_id"]);
 h+="<h2>Original costs and explicit allocation</h2><p>Each allocation retains the whole original transaction amount, its stable allocation key and this initiative's attributed amount. Negative reversals retain their own original transaction.</p>"+table(["Original transaction","Currency","Complete","Original amount","Allocated amount","Unallocated amount"],(r.costs?.groups||[]).map(x=>[String(x.economic_id).split("\u0000").join(" / "),x.currency,x.complete,n(x.transaction_amount),n(x.allocated_amount),n(x.unallocated_amount)]))+detailRows(r.costs?.canonical||[],"Individual source-backed allocations",["record_id"]);
 h+="<h2>Procurement submissions and Finance decisions</h2><p>Calculated, submitted and approved amounts remain distinct. Finance decisions bind the exact submitted row; corrections retain earlier decisions and require a current edition.</p>"+table(["Submission","Time","Submitted by","Currency","Price","Net","Avoidance","Source resolved"],(r.approvals?.submissions||[]).map(x=>[x.record_id,x.values?.submitted_at,x.values?.submitted_by,x.submitted?.currency,n(x.submitted?.price),n(x.submitted?.net),n(x.submitted?.avoidance),x.valid]));
 h+=table(["Finance decision","Submission","Time","Reviewer","Decision","Currency","Approved price","Approved net","Approved avoidance","Source resolved"],(r.approvals?.finance||[]).map(x=>[x.record_id,x.values?.submission_record_id,x.values?.reviewed_at,x.values?.reviewed_by,x.values?.decision,x.approved?.currency||x.values?.currency||"Unobserved",n(x.approved?.price),n(x.approved?.net),n(x.approved?.avoidance),x.valid]))+detailRows(r.approvals,"Complete dated approval history",["record_id"]);
 return h;
}

function render(){const view=session.view;document.querySelectorAll("nav button").forEach(b=>b.setAttribute("aria-current",b.dataset.view===view?"page":"false"));const fn={study:studyView,intake:intakeView,selection:selectionView,records:recordsView,plan:planView,commerce:commerceView,timeline:timelineView,crosswalks:crosswalkView,documents:documentsView,compare:compareView,reviews:reviewsView,recovery:recoveryView}[view]||studyView;$("main").innerHTML=fn();status();if(busy)freeze(true);}
function replace(next,msg,clearDraftKeys=[]){const nextEmergency=S.clone(emergency);for(const key of clearDraftKeys)delete nextEmergency.drafts[key];selectInstalled(next,nextEmergency);dirty=true;message=msg;persist();render();}
function retainBinary(kind,file,bytes,error){const base64=Binary.encode(bytes),p={kind,name:file.name,media_type:file.type||"application/octet-stream",base64,error,at:now()},key="pending-import:"+SHA.sha256Utf8(kind+"\0"+file.name+"\0"+base64).sha256;try{selectInstalled(M.draft(session,key,p));persist();}catch(e){if(!emergency.imports.some(x=>x.key===key))emergency.imports.push({key,...p});emergency.reason=e.message;dirty=true;}}
async function openFile(file,kind){if(!file)return;if(kind==="session"&&hasEmergency()){say("Download and clear pending recovery before opening another session.");return;}if(busy)return;freeze(true);let retainedText=null,retainedBytes=null;try{const before=M.hash(session);await flush();
 if(file.size>(kind==="session"?256:24)*1024*1024)throw Error("File exceeds the import limit; choose a smaller authorised cohort");
 const bytes=new Uint8Array(await file.arrayBuffer());retainedBytes=bytes;if(M.hash(session)!==before)throw Error("Session changed during the file read; the original candidate is retained");
 let next,nextEmergency=null,nextMetadata=installedMeta;
 if(kind==="document"){const study=Core.addDocument(session.study,{name:file.name,media_type:file.type||"application/octet-stream",bytes,at:now(),notes:"Exact original retained. Link to a source or returned record below."});next=M.checkpoint(session,study,"Retain original document "+file.name);next.view="documents";}
 else {const text=new TextDecoder("utf-8",{fatal:true,ignoreBOM:true}).decode(bytes);retainedText=text;
  if(kind==="session"){let x=JSON.parse(text.charCodeAt(0)===0xfeff?text.slice(1):text),pending=x.schema==="procurement-savings.source-emergency/v1"?x:null;if(pending)x=pending.session;if(x.schema===S.carrierSchema||x.schema===S.schema||x.schema==="stellar-forge.procurement-savings-emergency-carrier.v1"){const received=S.receive(x),joined=S.replace(getInstalled(),received,"Before opening complete installed carrier");x=joined.workspace;nextEmergency=joined.emergency;nextMetadata={actor:joined.draft.actor,retainedEmergency:joined.retainedEmergency};}
   if(x.schema===M.SCHEMA||x.schema===M.LEGACY){x=M.normalize(x);exportSession();next=M.takeSession(session,x,"Before imported replacement");}
   else {Core.validate(x);exportSession();next=M.use(session,x,"Before imported study replacement");}
   if(pending){if(!pending.pending_forms||typeof pending.pending_forms!=="object"||Array.isArray(pending.pending_forms)||!Array.isArray(pending.pending_imports))throw Error("Invalid emergency recovery");nextEmergency={drafts:{...pending.pending_forms},imports:[...pending.pending_imports],reason:pending.reason||"Imported pending recovery"};}
  } else if(kind.startsWith("csv:")){const [,recordKind,side]=kind.split(":");if(!Core.KINDS.includes(recordKind)||!["source","returned"].includes(side))throw Error("Choose record kind and side");const t=Core.inspectCSV(text),key="intake:"+recordKind+":"+side;
   next=retainForm(key,"Before replacing pending CSV "+key);next=M.draft(next,key,{kind:recordKind,side,name:file.name,content:text,label:file.name,at:now(),available_at:now(),mapping:Object.fromEntries(Core.FIELDS[recordKind].map(field=>[field,t.header.includes(field)?field:""]))});
   next.selection.intakeKind=recordKind;next.selection.intakeSide=side;next.view="intake";
  } else throw Error("Unknown import route");
 }
 const selectedEmergency=nextEmergency||S.clone(emergency);if(!nextEmergency&&kind.startsWith("csv:"))delete selectedEmergency.drafts["intake:"+kind.split(":")[1]+":"+kind.split(":")[2]];selectInstalled(next,selectedEmergency,nextMetadata);dirty=true;message="Opened "+file.name+". Prior applied state and unfinished forms remain recoverable.";persist();
 }catch(e){if(retainedText!==null)retainImport(kind,file.name,retainedText,e.message);else if(retainedBytes)retainBinary(kind,file,retainedBytes,e.message);message=e.message+" — selected study and readable import candidate retained.";}
 finally{freeze(false);render();}
}
async function adoptLocal(){freeze(true);try{await flush();const local=getInstalled(),out=await localRecovery.adopt(db,localKey,{schema:"stellar-forge.procurement-savings-local.v1",carrier:S.pack(local)},(selected,previous)=>{const prior=previous?S.receive(previous.carrier):local,joined=S.replace(prior,local,"Explicit adoption retains both browser preimages");return {...selected,carrier:S.pack(joined)};});setInstalled(S.receive(out.value.carrier));seen=out.sha256;conflict=false;storageError="";dirty=false;message="This complete branch is selected; both preimages remain recoverable.";}catch(e){storageError=e.message;dirty=true;message="Adoption failed; complete working state remains retained.";}finally{freeze(false);render();}}
async function action(el){if(busy)return;const act=el.dataset.action;try{if(hasEmergency()&&["new-study","course","open-branch","restore-edition","open-saved"].includes(act))throw Error("Resolve or download-and-clear pending input in Save & recover before replacing the study.");
 if(act==="installed-working"){try{download("Procurement_Savings_Reconciliation_Study_Working.json",Core.json(S.pack(getInstalled())));}catch(e){download("Procurement_Savings_Reconciliation_Study_Complete_Emergency.json",Core.json(emergencyCarrier()));say(e.message+" Complete original session, pending inputs and installed metadata are in the emergency file.");}}
 else if(act==="installed-editable"){download("Procurement_Savings_Reconciliation_Study_Editable.html",buildProcurementSavingsStudyDesk(Object.fromEntries(sourceFiles.map(x=>[x.path,x.content])),{carrier:S.pack(getInstalled())}),"text/html");}
 else if(act==="installed-handover"){if(managed)await managed.export();else{const carrier=S.pack(getInstalled()),state={installationId:"standalone",sha256:carrier.sha256,sequence:0,carrier,receipts:[],rejections:[]};download("Procurement_Savings_Reconciliation_Study_Full_Handover.zip",buildProcurementSavingsStudyExport(Object.fromEntries(sourceFiles.map(x=>[x.path,x.content])),state,[],[],{codec:C,core:Core,originalSessions:M,sessions:S,buildDesk:buildProcurementSavingsStudyDesk,zip:window.ProcurementSavingsStudyZIP}),"application/zip");}}
 else if(act==="download-session")exportSession();
 else if(act==="export-zip"){await flush();download("procurement-savings-source-complete.zip",ZIP.write(M.exports(session).concat([{path:"installed-working.json",content:Core.json(S.pack(getInstalled()))}],hasEmergency()?[{path:"emergency-recovery.json",content:Core.json(recoveryEnvelope())}]:[])),"application/zip");say("Complete study, report, editable tables, originals and branches exported.");}
 else if(act==="export-source"){download("procurement-savings-source-application-source.zip",ZIP.write(sourceFiles),"application/zip");say("Complete application source downloaded.");}
 else if(act==="report"){const a=M.assess(session);if(!a.ok)throw Error(a.error);download("procurement-savings-source-report.md",Core.report(session.study,a.result),"text/markdown");}

 else if(act==="csv-template"){if(!Core.KINDS.includes(el.dataset.kind))throw Error("Unknown record kind");download(el.dataset.kind+".csv",CSV.csv([Core.FIELDS[el.dataset.kind]]),"text/csv");}
 else if(act==="clear-emergency"){if(!confirm("Download the complete emergency file and clear its pending input? Applied study remains."))return;download("Procurement_Savings_Reconciliation_Study_Complete_Emergency.json",Core.json(emergencyCarrier()));const next=S.fromSession(session,S.emptyEmergency(),installedMeta);setInstalled(next);persist();render();say("Complete pending input downloaded and cleared. Earlier retained emergencies and operation actor remain.");}
 else if(act==="download-emergency-import"){const p=emergency.imports.find(x=>x.key===el.dataset.key);if(!p)throw Error("Pending import missing");download(p.name,p.base64?Binary.decode(p.base64):p.text,p.media_type||"text/plain");}

 else if(act==="record-kind"||act==="record-side"){const next=M.clone(session);if(act==="record-kind")next.selection.recordKind=el.dataset.kind;else if(act==="record-side")next.selection.recordSide=el.dataset.side;next.revision++;replace(next,"Selection changed; unfinished forms retained.");}
 else if(act==="new-record"||act==="edit-record"){const kind=(Core.KINDS.includes(session.selection.recordKind)?session.selection.recordKind:Core.KINDS[0]),side=(["source","returned"].includes(session.selection.recordSide)?session.selection.recordSide:"returned"),key="record:"+kind+":"+side;let value=recordBase(kind,side);if(act==="edit-record"){const i=Number(el.dataset.index),row=Core.rows(session.study,kind,side)[i];if(!row)throw Error("Selected row missing");value.row_index=i;value.value=M.clone(row.values);}let next=retainForm(key,"Before preparing another record");next=M.draft(next,key,value);replace(next,"Record editor prepared; previous draft is recoverable.",[key]);}


 else if(act==="refresh-record-helpers"){render();}
  else if(act==="record-procurement-bindings"){const kind=Core.KINDS.includes(session.selection.recordKind)?session.selection.recordKind:Core.KINDS[0],side=["source","returned"].includes(session.selection.recordSide)?session.selection.recordSide:"returned",key="record:"+kind+":"+side,v=M.clone(draftValue(key,recordBase(kind,side)));if(v.study_id!==session.study.id||v.expected_extract_id!==(Core.selected(session.study,kind,side)?.id||null))throw Error("Prepare a current source-bound draft");const patch=Procurement.sourceBindings(session.study,Core.rows,Core.selected,side,kind,v.value);for(const[k,value]of Object.entries(patch)){if(v.value[k]===null)throw Error("Map "+k+" first");v.value[k]=value;}let next=retainForm(key,"Before exact procurement source binding");next=M.draft(next,key,v);replace(next,"Exact supplied source bindings retained in the pending record.",[key]);}
  else if(act==="record-document-digest"){const kind=Core.KINDS.includes(session.selection.recordKind)?session.selection.recordKind:Core.KINDS[0],side=(["source","returned"].includes(session.selection.recordSide)?session.selection.recordSide:"returned"),key="record:"+kind+":"+side,v=M.clone(draftValue(key,recordBase(kind,side))),field=["sha256"].find(k=>Core.FIELDS[kind].includes(k)),doc=session.study.documents.find(x=>x.id===v.digest_document_id);if(!field||!doc)throw Error("Choose an exact retained original for this record");if(v.value[field]===null)throw Error("Map this unobserved digest field explicitly before editing");let next=retainForm(key,"Before selecting exact original digest");v.value[field]=doc.sha256;next=M.draft(next,key,v);replace(next,"Exact original digest copied into the retained draft. Record and link it using the actual source context.",[key]);}
 else if(act==="edit-document-availability"){const d=session.study.documents.find(x=>x.id===el.dataset.id);if(!d)throw Error("Document missing");let next=retainForm("document-availability","Before revising document availability");next=M.draft(next,"document-availability",{study_id:session.study.id,document_id:d.id,expected_sha256:d.sha256,expected_metadata_sha256:Core.hash(d),available_at:d.available_at,reason:"",at:now()});replace(next,"Document availability editor prepared; exact bytes and previous metadata retained.",["document-availability"]);}
 else if(act==="preview-document"){const next=M.clone(session);next.selection.previewDocument=el.dataset.id;next.revision++;replace(next,"Selected retained photo.");}
 else if(act==="new-review"){let next=M.retain(session,session,"Before explicitly restarting review");const old=draftValue("review",null);if(old)next=M.draft(next,"retained-review:"+M.hash(old),old);next=M.draft(next,"review",M.reviewDraft(session));replace(next,"Review started for the current complete comparison. Previous notes remain retained.",["review"]);}
 else if(act==="new-study"){if(!confirm("Start an empty study? Current complete session is retained and downloaded first."))return;exportSession();replace(M.use(session,Core.empty(),"Before new empty study"),"Empty procurement and outcome study opened.");}
 else if(act==="course"){if(!confirm("Open the authored example? It contains fictional procurement-savings records. Current session is retained."))return;exportSession();const k=el.dataset.course;if(!courses[k])throw Error("Select an example");replace(M.use(session,courses[k],"Before authored "+k+" study"),"Authored "+k+" study opened.");}
 else if(["intake-kind","intake-side","map-kind"].includes(act)){const next=M.clone(session);if(act==="intake-kind")next.selection.intakeKind=el.dataset.kind;else if(act==="intake-side")next.selection.intakeSide=el.dataset.side;else next.selection.mapKind=el.dataset.kind;next.revision++;replace(next,"Selection updated; pending forms retained.");}
 else if(act==="add-pair"||act==="remove-pair"){const kind=(Core.KINDS.includes(session.selection.mapKind)?session.selection.mapKind:Core.KINDS[0]),key="crosswalk:"+kind,base={kind,pairs:session.study.crosswalks.filter(x=>x.kind===kind).map(({source_id,target_id})=>({source_id,target_id}))},v=M.clone(draftValue(key,base));let next=retainForm(key,"Before changing draft identity pairs");if(act==="add-pair")v.pairs.push({source_id:"",target_id:""});else v.pairs.splice(Number(el.dataset.index),1);next=M.draft(next,key,v);replace(next,"Draft identity pairs updated.",[key]);}
 else if(act==="match-ids"){const kind=el.dataset.kind,key="crosswalk:"+kind;let next=retainForm(key,"Before adding exact-ID pairs");next=M.checkpoint(next,Core.matchIds(next.study,kind),"Add unique exact-ID maps");delete next.drafts[key];replace(next,"Unique identical IDs added. Earlier applied maps and drafts remain recoverable.",[key]);}
 else if(act==="edit-extract"){const e=session.study.extracts.find(x=>x.id===el.dataset.id);if(!e)throw Error("Extract missing");const o=session.study.originals.find(x=>x.id===e.original_id),key="intake:"+e.kind+":"+e.side;let next=retainForm(key,"Before editing mapping "+e.id);next=M.draft(next,key,{kind:e.kind,side:e.side,name:o.name,content:o.content,label:e.label,at:now(),available_at:e.available_at,mapping:M.clone(e.mapping)});next.selection.intakeKind=e.kind;next.selection.intakeSide=e.side;next.view="intake";replace(next,"Mapping revision prepared; original extract remains retained.",[key]);}
 else if(act==="download-intake"){const p=draftValue(el.dataset.key,null);if(!p)throw Error("Pending CSV missing");download(p.name,p.content,"text/csv");}
 else if(act==="unlink-document"){const link=session.study.document_links[Number(el.dataset.index)];if(!link)throw Error("Link not found");if(!confirm("Remove this exact record-document link from the selected study? Its document and complete prior edition remain retained."))return;replace(M.checkpoint(session,Core.unlinkDocument(session.study,link),"Remove explicit record-document link"),"Link removed. Exact document and prior relationship remain recoverable.");}
 else if(act==="download-document"){const d=session.study.documents.find(x=>x.id===el.dataset.id);if(!d)throw Error("Document missing");download(d.name,Binary.decode(d.base64),d.media_type);}
 else if(act==="reset-draft"){let next=retainForm(el.dataset.key,"Before resetting draft "+el.dataset.key);delete next.drafts[el.dataset.key];next.revision++;replace(next,"Form reset; previous form is in recovery.",[el.dataset.key]);}
 else if(act==="download-pending"){const p=session.drafts[el.dataset.key];if(!p)throw Error("Import candidate not found");download(p.name,p.base64?Binary.decode(p.base64):p.text,p.media_type||"text/plain");}
 else if(act==="retry-pending"){const p=session.drafts[el.dataset.key];if(!p)throw Error("Import candidate not found");await openFile(new File([p.base64?Binary.decode(p.base64):p.text],p.name,{type:p.media_type||"text/plain"}),p.kind);}
 else if(act==="save-notes"){const st=M.clone(session.study);st.notes=draftValue("study-notes",{})?.text??$("study-notes").value;replace(M.checkpoint(session,st,"Save study notes"),"Notes saved.");}
 else if(act==="download-original"){const o=session.study.originals.find(x=>x.id===el.dataset.id);if(!o)throw Error("Original not found");download(o.name,o.content,"text/plain");}
 else if(act==="download-branch"){const b=session.backups.find(b=>b.hash===el.dataset.id);if(!b)throw Error("Branch not found");download("procurement-savings-source-branch-"+b.hash.slice(0,12)+".json",Core.json(M.branchSession(session,b)));}
 else if(act==="open-branch"){const b=session.backups.find(b=>b.hash===el.dataset.id);if(!b)throw Error("Branch not found");exportSession();replace(M.takeSession(session,M.branchSession(session,b),"Before opening retained branch"),"Retained branch opened. If another saved copy exists, acknowledge it explicitly.");}
 else if(act==="restore-edition"){const h=session.history[Number(el.dataset.index)];if(!h)throw Error("Edition not found");exportSession();replace(M.use(session,M.historyStudy(session,h),"Before restoring study edition"),"Study edition restored; complete prior session retained.");}
 else if(act==="adopt-local")await adoptLocal();
 else if(act==="open-saved"){freeze(true);await flush();const old=await readActive();if(!old)throw Error("No saved copy exists");exportSession();const next=S.replace(getInstalled(),old.installed,"Local session before opening saved branch");seen=old.hash;setInstalled(next);conflict=false;dirty=true;persist();message="Saved branch opened; local branch retained.";freeze(false);render();}
 }catch(e){freeze(false);say(e.message);}}
document.addEventListener("input",e=>{if(busy)return;if(e.target.id==="record-filter"){const q=e.target.value.toLowerCase();document.querySelectorAll("[data-filter]").forEach(x=>x.hidden=!x.dataset.filter.includes(q));return;}if(e.target.id==="study-notes"){recordDraft("study-notes",{text:e.target.value});return;}const form=e.target.closest("form[data-key]");if(form){recordDraft(form.dataset.key,collect(form));}});
document.addEventListener("change",e=>{if(e.target.dataset.file)openFile(e.target.files?.[0],e.target.dataset.file);else if(!busy&&e.target.dataset.selectionKind){try{const kind=e.target.dataset.selectionKind,side=e.target.dataset.selectionSide;replace(M.checkpoint(session,Core.choose(session.study,kind,side,e.target.value),"Select "+side+" "+kind),"Selected exact retained edition.");}catch(err){say(err.message);render();}}else if(!busy&&e.target.matches("select")){const form=e.target.closest("form[data-key]");if(form){recordDraft(form.dataset.key,collect(form));if(form.dataset.key==="document-link"&&["side","kind"].includes(e.target.dataset.path)||form.dataset.kind==="record"&&["value.family","value.source_family"].includes(e.target.dataset.path))render();}}});
document.addEventListener("submit",e=>{const form=e.target.closest("form[data-key]");if(!form)return;e.preventDefault();if(busy)return;try{const value=collect(form,true),kind=form.dataset.kind;let next;
 if(kind==="config"){const st=M.clone(session.study);st.config={...st.config,...value};next=M.checkpoint(session,st,"Save study scope");}

 else if(kind==="record"){if(value.study_id!==session.study.id||value.expected_extract_id!==(Core.selected(session.study,value.kind,value.side)?.id||null))throw Error("Selected records changed after this draft began; retain it and prepare a fresh correction");next=M.checkpoint(session,Core.editRow(session.study,value),"Record source-backed "+value.kind+" revision");}
 else if(kind==="procurement-plan"){const st=M.clone(session.study);st.config.procurement={...st.config.procurement,...value};next=M.checkpoint(session,st,"Revise complete initiative population and recurring work plan");}

 else if(kind==="review")next=M.recordReview(session,value);
 else if(kind==="intake")next=M.checkpoint(session,Core.importExtract(session.study,value),"Retain original and mapped extract "+value.kind);
 else if(kind==="crosswalk")next=M.checkpoint(session,Core.crosswalk(session.study,value.kind,value.pairs),"Apply explicit identity map "+value.kind);
 else if(kind==="document-availability")next=M.checkpoint(session,Core.documentAvailability(session.study,value),"Retain sourced document availability");
 else if(kind==="document-link")next=M.checkpoint(session,Core.linkDocument(session.study,value),"Link retained record document");
 else throw Error("Unknown form");
 next=M.retain(next,session,"Complete form before saving "+form.dataset.key);delete next.drafts[form.dataset.key];replace(next,"Saved "+kind+". Comparison retains every unresolved field and source difference.",[form.dataset.key]);
 }catch(err){say(err.message+" — unfinished form retained.");}});
document.addEventListener("click",e=>{const el=e.target.closest("button");if(!el||busy)return;if(el.dataset.view){try{const next=M.clone(session);next.view=el.dataset.view;next.revision++;selectInstalled(next);persist();render();}catch(err){say(err.message);render();}}else if(el.dataset.action)action(el);});
